1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	};
34	
35	const COMPONENT_BLOCK_SIZE = 3;
36	const COMPONENT_BLOCK_PREMIUM = 60;
37	
38	const isComponentBlock = (items: Item[]): boolean =>
39	  items.length === COMPONENT_BLOCK_SIZE;
40	
41	// Only the "3 alike form one block" case is implemented; the block is still
42	// detected by item count alone, so a mixed trio would be discounted wrongly.
43	// The pending "2 runes + 1 moonstone" and "3 runes + 3 moonstones" tests will
44	// force grouping by item type.
45	const totalBasePremium = (items: Item[]): number => {
46	  if (isComponentBlock(items)) return COMPONENT_BLOCK_PREMIUM;
47	  return items.reduce((total, item) => total + BASE_PREMIUMS[item.type], 0);
48	};
49	
50	const quotePremium = (items: Item[]): number => {
51	  const base = totalBasePremium(items);
52	  // Keep the surcharge additive (base + base * rate). The algebraically
53	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
54	  // which Math.ceil turns into a premium that is 1 G too high.
55	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
56	  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
57	};
58	
59	export const runScenario = (scenario: Scenario): Result[] =>
60	  scenario.steps.map((step) => {
61	    if (step.op === "quote") return { premium: quotePremium(step.items) };
62	    throw new Error(`Unsupported step: ${step.op}`);
63	  });
