const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const formsBlock = (alikeItems: Item[]): boolean =>
  alikeItems.length === COMPONENT_BLOCK_SIZE;

const basePremiumForAlikeItems = (alikeItems: Item[]): number => {
  if (formsBlock(alikeItems)) return COMPONENT_BLOCK_PREMIUM;
  return alikeItems.length * BASE_PREMIUMS[alikeItems[0].type];
};

const totalBasePremium = (items: Item[]): number =>
  groupByType(items).reduce(
    (total, alikeItems) => total + basePremiumForAlikeItems(alikeItems),
    0,
  );
